(2292647, 316339, 35513, '<td valign="top">Very nice clarity and lighting, though it looks just a tad oversharpened to me.</td>', 'Very nice clarity and lighting, though it looks just a tad oversharpened to me.', '2006-04-06 19:25:09.000000', NULL, 1),
(2292654, 316751, 35513, '<td valign="top">Great shot!  Lighting look fabulous and the clarity is great.  Love the color in the flower and the simple elegance of this shot.</td>', 'Great shot!  Lighting look fabulous and the clarity is great.  Love the color in the flower and the simple elegance of this shot.', '2006-04-06 19:29:14.000000', NULL, 1),
(2292657, 316239, 35513, '<td valign="top">Great detail on this shot!  The lighting looks a little bit dark to me...perhaps a small bump in brightness might help.  Love the sunset in the background!</td>', 'Great detail on this shot!  The lighting looks a little bit dark to me...perhaps a small bump in brightness might help.  Love the sunset in the background!', '2006-04-06 19:31:22.000000', NULL, 1),
