(2292888, 314023, 51802, '<td valign="top">I like the combination of blue and white.</td>', 'I like the combination of blue and white.', '2006-04-06 21:28:33.000000', NULL, 1),
(2292903, 315570, 51802, '<td valign="top">A little bit deeper DOF would put this picture over the top.  If the bottle were in sharp focus with the glass, but keeping the flowers in the background out of focus, it would give this picture a lot more pop.</td>', 'A little bit deeper DOF would put this picture over the top.  If the bottle were in sharp focus with the glass, but keeping the flowers in the background out of focus, it would give this picture a lot more pop.', '2006-04-06 21:33:47.000000', NULL, 1),
