(2297328, 316239, 56545, '<td valign="top">very nice... I like the refraction of the sunset in the stem and the angle on the glass to see two olives.... nice examples of refraction.</td>', 'very nice... I like the refraction of the sunset in the stem and the angle on the glass to see two olives.... nice examples of refraction.', '2006-04-08 10:18:30.000000', NULL, 1),
(2297330, 316588, 37961, '<td valign="top">Good idea. Would like to see a little more of the unrefracted flowers but still...cool image.</td>', 'Good idea. Would like to see a little more of the unrefracted flowers but still...cool image.', '2006-04-08 10:19:21.000000', NULL, 1),
(2297331, 316860, 37961, '<td valign="top">Love the way the light makes its own design on the fabric. Nice.</td>', 'Love the way the light makes its own design on the fabric. Nice.', '2006-04-08 10:20:05.000000', NULL, 1),
(2297332, 316873, 56545, '<td valign="top">Love the glint of light off the red sand crystals... nice work.</td>', 'Love the glint of light off the red sand crystals... nice work.', '2006-04-08 10:21:05.000000', NULL, 1),
(2297335, 316821, 56545, '<td valign="top">you need to have your subject in focus - either the red-looking sign in the background, or - for a Refraction of Light theme - the raindrops on the glass... right now everything is out of focus</td>', 'you need to have your subject in focus - either the red-looking sign in the background, or - for a Refraction of Light theme - the raindrops on the glass... right now everything is out of focus', '2006-04-08 10:24:17.000000', NULL, 1),
(2297339, 314393, 56545, '<td valign="top">Great job... love the sharpness of the world in the glass vs. the blur of the one in the background - great depth of field control</td>', 'Great job... love the sharpness of the world in the glass vs. the blur of the one in the background - great depth of field control', '2006-04-08 10:26:31.000000', NULL, 1),
