(2297347, 316711, 56545, '<td valign="top">Nice work... looks great.</td>', 'Nice work... looks great.', '2006-04-08 10:33:10.000000', NULL, 1),
(2297358, 316337, 56545, '<td valign="top">Beautiful interpretation on Refraction...</td>', 'Beautiful interpretation on Refraction...', '2006-04-08 10:36:18.000000', NULL, 1),
(2297361, 315025, 56545, '<td valign="top">Nice capture of colours...</td>', 'Nice capture of colours...', '2006-04-08 10:36:57.000000', NULL, 1),
(2297363, 316896, 56545, '<td valign="top">Very clean... nice job.</td>', 'Very clean... nice job.', '2006-04-08 10:39:05.000000', NULL, 1),
