INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2297388, 316344, 51812, '<td valign="top">Breath-taking. Love the monochromatic effect.</td>', 'Breath-taking. Love the monochromatic effect.', '2006-04-08 11:03:47.000000', NULL, 1),
(2297397, 316239, 43031, '<td valign="top">I''m thinking you should have lit the background up instead of the glass, and let the light shine through, those reflections are distracting from an otherwise very good refraction. Also having the glass off-center makes me feel lopsided.</td>', 'I''m thinking you should have lit the background up instead of the glass, and let the light shine through, those reflections are distracting from an otherwise very good refraction. Also having the glass off-center makes me feel lopsided.', '2006-04-08 11:12:44.000000', NULL, 1),
(2297522, 316703, 14614, '<td valign="top">wonderfully creative -- really like your idea here -- one of my favorites this challenge (bumping up -- one of my ribbon picks)</td>', 'wonderfully creative -- really like your idea here -- one of my favorites this challenge (bumping up -- one of my ribbon picks)', '2006-04-08 12:46:21.000000', NULL, 1),
(2297524, 316363, 14614, '<td valign="top">crispy focus, wonderful colors and composition is spot on -- one of my ribbon picks</td>', 'crispy focus, wonderful colors and composition is spot on -- one of my ribbon picks', '2006-04-08 12:46:54.000000', NULL, 1),
(2297525, 316522, 14614, '<td valign="top">wonderful blend of busy composition balanced with monochromatic tones. one of my ribbon picks</td>', 'wonderful blend of busy composition balanced with monochromatic tones. one of my ribbon picks', '2006-04-08 12:47:27.000000', NULL, 1),
(2297528, 316751, 14614, '<td valign="top">really like the juxtapositon of the two flowers agains the simple background,  great eye for composition and color. one of my ribbon picks</td>', 'really like the juxtapositon of the two flowers agains the simple background,  great eye for composition and color. one of my ribbon picks', '2006-04-08 12:48:18.000000', NULL, 1),
