(2297545, 314819, 41200, '<td valign="top">Beautiful image.</td>', 'Beautiful image.', '2006-04-08 12:57:20.000000', NULL, 1),
(2297546, 316157, 41200, '<td valign="top">Outstanding idea! You must have a lot of patience.</td>', 'Outstanding idea! You must have a lot of patience.', '2006-04-08 12:58:41.000000', NULL, 1),
