INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2306293, 316703, 36382, '<td valign="top">The grid is pretty small, each square is about .5 cm.  The whole set up was horizontal so that the drops would be fat in the middle and not drip downwards.  Needed loads of patience manipulating the drops.  Knew I was spending too much time on this picture when I could see tiny little faces looking at me every time I blinked.<br/><br/><i>Message edited by author 2006-04-12 08:59:59.</i></td>', 'The grid is pretty small, each square is about .5 cm.  The whole set up was horizontal so that the drops would be fat in the middle and not drip downwards.  Needed loads of patience manipulating the drops.  Knew I was spending too much time on this picture when I could see tiny little faces looking at me every time I blinked.', '2006-04-12 09:57:19.000000', '2006-04-12 09:59:59.000000', 0),
(2306328, 316337, 29784, '<td valign="top">Oh, cool!  I''m glad this one got a ribbon.  It was my favorite one.  Congratulations!</td>', 'Oh, cool!  I''m glad this one got a ribbon.  It was my favorite one.  Congratulations!', '2006-04-12 10:11:15.000000', NULL, 0),
